import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Test Framework in Handl","description":"","frontmatter":{"title":"Test Framework in Handl","type":"adr","date":"2026-09-05T00:00:00.000Z","status":"implemented","status_note":"Implemented — the framework is handl; `plugin-lib-test` is deleted."},"headers":[],"relativePath":"handl/project/adrs/0092-test-framework-in-handl.md","filePath":"vendored/handl/project/adrs/0092-test-framework-in-handl.md"}'),a={name:`handl/project/adrs/0092-test-framework-in-handl.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0092-test-framework-in-handl" tabindex="-1">ADR-0092: Test Framework in Handl <a class="header-anchor" href="#adr-0092-test-framework-in-handl" aria-label="Permalink to “ADR-0092: Test Framework in Handl”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Target layout</strong>: the framework lives in <code>handl-packages/test/</code> as handl modules — <code>assert</code>, <code>property</code>, <code>benchmark</code>, <code>fuzz</code>, <code>snapshot</code> — with the <code>op</code>/<code>handl</code> declarations in <code>test.hnl</code>.</li><li><strong>Migration per op</strong>: each framework operation moves from Rust to a handl module, one op at a time, with parity tests.</li><li><strong>Crate boundary</strong>: <code>plugin-lib-test</code> is deleted; the runner (<code>engine-test</code>) consumes the framework through the module chain.</li><li><strong>Relationship to ADR-0089</strong>: the runner stays Rust; this ADR moves only the framework contract.</li><li><strong>Relationship to ADR-0077</strong>: the framework is part of the stdlib migration; every public arrow carries a doc comment and an axiom.</li><li><strong>What stays Rust</strong>: the test runner only.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The framework library was Rust <code>Function</code> bodies beside a Rust runner, so a framework change meant a rebuild and the assertion semantics could not be inspected. Handl modules make the framework data and leave only the runner in Rust.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep the framework in Rust</strong> — the duplication ADR-0077 removes.</li><li><strong>Move the runner too</strong> — ADR-0089 keeps it Rust; RFC-0005 tracks the port.</li><li><strong>One big-bang migration</strong> — one op at a time with parity tests.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The framework is handl; <code>plugin-lib-test</code> is gone.</li><li>The runner consumes the framework through the module chain.</li><li>Each op has a parity test before the Rust body is deleted.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>handl-packages/test/</code> — <code>test.hnl</code> and the five modules.</li><li><code>engine-test/</code> — the runner and its framework dependency.</li><li>Parity tests per migrated op.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Target layout, per-op migration, crate boundary and the ADR relationships: +<a href="./../design/0092-test-framework-in-handl.html"><code>design/0092-test-framework-in-handl.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};